-- ---------------------------------------------------------------------------------------------------- hand-written below
-- The outbound request guard (replaces the 0004 function; every 0004 rule is kept). Added: origin, the BOT bindings and the
-- control sequence are immutable, and a BOT request can never go back from SENDING to QUEUED (V3.2 I.4: a BOT refusal after
-- the claim is HELD, never re-queued). STAFF keeps SENDING -> QUEUED for results that prove nothing was sent.
CREATE OR REPLACE FUNCTION outbound_requests_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
	IF NEW.organization_id IS DISTINCT FROM OLD.organization_id
		OR NEW.whatsapp_account_id IS DISTINCT FROM OLD.whatsapp_account_id
		OR NEW.conversation_id IS DISTINCT FROM OLD.conversation_id
		OR NEW.message_id IS DISTINCT FROM OLD.message_id
		OR NEW.requested_by_membership_id IS DISTINCT FROM OLD.requested_by_membership_id
		OR NEW.idempotency_key IS DISTINCT FROM OLD.idempotency_key
		OR NEW.request_fingerprint IS DISTINCT FROM OLD.request_fingerprint
		OR NEW.message_type IS DISTINCT FROM OLD.message_type
		OR NEW.template_id IS DISTINCT FROM OLD.template_id
		OR NEW.recipient_kind IS DISTINCT FROM OLD.recipient_kind
		OR NEW.recipient_id IS DISTINCT FROM OLD.recipient_id
		OR NEW.payload IS DISTINCT FROM OLD.payload
		OR NEW.dispatch_deadline IS DISTINCT FROM OLD.dispatch_deadline
		OR NEW.created_at IS DISTINCT FROM OLD.created_at
		OR NEW.origin IS DISTINCT FROM OLD.origin
		OR NEW.bot_session_id IS DISTINCT FROM OLD.bot_session_id
		OR NEW.bot_step_seq IS DISTINCT FROM OLD.bot_step_seq
		OR NEW.bot_send_epoch IS DISTINCT FROM OLD.bot_send_epoch
		OR NEW.control_seq IS DISTINCT FROM OLD.control_seq THEN
		RAISE EXCEPTION 'outbound_requests: the request itself is immutable' USING ERRCODE = 'check_violation';
	END IF;
	IF NEW.state IS DISTINCT FROM OLD.state AND NOT (
		(OLD.state = 'QUEUED' AND NEW.state IN ('SENDING', 'HELD'))
		OR (OLD.state = 'SENDING' AND NEW.state IN ('ACCEPTED', 'REJECTED', 'UNKNOWN_OUTCOME', 'HELD'))
		OR (OLD.state = 'SENDING' AND NEW.state = 'QUEUED' AND OLD.origin = 'STAFF')
	) THEN
		RAISE EXCEPTION 'outbound_requests: illegal state change % -> % (%)', OLD.state, NEW.state, OLD.origin USING ERRCODE = 'check_violation';
	END IF;
	RETURN NEW;
END $$;
--> statement-breakpoint
-- Control sequences for staff rows (V3.2 J.1, K.10). Every outbound request (STAFF and BOT) and every conversation event gets
-- the next value of its conversation's counter, allocated by the database under the conversation row lock; any value the
-- writer supplied is overwritten. The allocator changes conversations.control_seq only (no activity timestamp).
CREATE FUNCTION outbound_requests_allocate_control_seq() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
	-- A conversation of another organization (or none): leave the row to the foreign key, which rejects it with its own name.
	-- A row that passes its foreign key therefore always has a control sequence.
	PERFORM 1 FROM "conversations" WHERE organization_id = NEW.organization_id AND id = NEW.conversation_id;
	IF FOUND THEN
		NEW.control_seq := allocate_conversation_control_seq(NEW.organization_id, NEW.conversation_id);
	ELSE
		NEW.control_seq := NULL;
	END IF;
	RETURN NEW;
END $$;
--> statement-breakpoint
CREATE TRIGGER outbound_requests_allocate_control_seq_trg BEFORE INSERT ON "outbound_requests" FOR EACH ROW EXECUTE FUNCTION outbound_requests_allocate_control_seq();
--> statement-breakpoint
CREATE FUNCTION conversation_events_allocate_control_seq() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
	-- A conversation of another organization (or none): leave the row to the foreign key, which rejects it with its own name.
	-- A row that passes its foreign key therefore always has a control sequence.
	PERFORM 1 FROM "conversations" WHERE organization_id = NEW.organization_id AND id = NEW.conversation_id;
	IF FOUND THEN
		NEW.control_seq := allocate_conversation_control_seq(NEW.organization_id, NEW.conversation_id);
	ELSE
		NEW.control_seq := NULL;
	END IF;
	RETURN NEW;
END $$;
--> statement-breakpoint
CREATE TRIGGER conversation_events_allocate_control_seq_trg BEFORE INSERT ON "conversation_events" FOR EACH ROW EXECUTE FUNCTION conversation_events_allocate_control_seq();
--> statement-breakpoint
-- The BOT dispatch rule (V3.2 I.4 and I.5), one statement, used by BOTH the claim and the final pre-HTTP authorization so they
-- apply the same rule. STABLE: it sees the snapshot of the statement that calls it. NULL means "may be sent" as far as the bot
-- is concerned (the window, contact and recipient are evaluated by the dispatcher with a fresh clock); otherwise a hold code.
-- It reads only protected columns (never a redactable one), so privacy redaction can neither enable nor block a send. A STAFF
-- request returns NULL (not applicable). Staff control rows written before 0008 have control_seq NULL: earlier than any session.
CREATE FUNCTION bot_request_hold_code(p_organization_id uuid, p_request_id uuid) RETURNS text LANGUAGE sql STABLE AS $$
	SELECT CASE
		WHEN r.id IS NULL THEN 'bot_state_unreadable'
		WHEN r.origin <> 'BOT' THEN NULL
		WHEN s.id IS NULL OR d.id IS NULL OR b.id IS NULL THEN 'bot_state_unreadable'
		WHEN d.status = 'RETIRED' THEN 'bot_deployment_inactive'
		WHEN d.status = 'STOPPED' THEN 'bot_stopped'
		WHEN d.status NOT IN ('ACTIVE', 'PAUSED') THEN 'bot_deployment_inactive'
		WHEN d.send_epoch IS DISTINCT FROM r.bot_send_epoch THEN 'bot_epoch_superseded'
		WHEN b.archived_at IS NOT NULL THEN 'bot_archived'
		WHEN s.output_suppressed_at IS NOT NULL THEN 'bot_output_suppressed'
		-- (a) live session: only its current step, while it waits for this send
		WHEN s.state IN ('ACTIVE', 'WAITING_FOR_SEND', 'WAITING_FOR_INPUT')
			AND NOT (s.state = 'WAITING_FOR_SEND' AND r.bot_step_seq = s.step_seq) THEN 'bot_step_superseded'
		-- (b) terminal session: only the terminal notice it recorded
		WHEN s.state NOT IN ('ACTIVE', 'WAITING_FOR_SEND', 'WAITING_FOR_INPUT')
			AND NOT (s.state IN ('COMPLETED', 'HANDED_OVER')
				AND s.terminal_notice_step_seq IS NOT NULL
				AND r.bot_step_seq = s.terminal_notice_step_seq) THEN 'bot_session_ended'
		-- staff control sequenced after the session start (J.1, J.2 rules 4-6)
		WHEN EXISTS (
			SELECT 1 FROM conversation_events e
			WHERE e.organization_id = r.organization_id AND e.conversation_id = r.conversation_id
				AND e.kind = 'STATUS' AND e.to_status = 'RESOLVED' AND e.control_seq > s.started_control_seq
		) THEN 'conversation_resolved'
		WHEN EXISTS (
			SELECT 1 FROM conversation_events e
			WHERE e.organization_id = r.organization_id AND e.conversation_id = r.conversation_id
				AND e.control_seq > s.started_control_seq
		) OR EXISTS (
			SELECT 1 FROM outbound_requests x
			WHERE x.organization_id = r.organization_id AND x.conversation_id = r.conversation_id
				AND x.origin = 'STAFF' AND x.control_seq > s.started_control_seq
		) THEN 'staff_took_over'
		ELSE NULL
	END
	FROM (SELECT p_organization_id AS org, p_request_id AS rid) k
	LEFT JOIN outbound_requests r ON r.organization_id = k.org AND r.id = k.rid
	LEFT JOIN bot_sessions s ON s.organization_id = r.organization_id AND s.id = r.bot_session_id
	LEFT JOIN bot_deployments d ON d.organization_id = s.organization_id AND d.id = s.deployment_id
	LEFT JOIN bots b ON b.organization_id = s.organization_id AND b.id = s.bot_id
$$;
